                vectorMaxCount: 500,           // [v2.9] RU-B: 向量硬上限
                summaryMaxCount: 400,          // [v2.9] RU-B: 摘要硬上限
                optimizeEveryFloors: 50,       // [v2.9] RU-B: 优化周期（楼）
