                if (!ev || ev.type !== anchor.type) return false;
                if (ev.type === 'fantasy') return ev.monthId === anchor.monthId && Math.abs((ev.day || 0) - (anchor.day || 0)) <= Math.max(0, Number(windowDays) || 0);
                if (ev.year == null || anchor.year == null) return false;
